import java.util.*;

class BrowserHistory {
    private final List<String> history = new ArrayList<>();
    private int currentIndex;
    private int lastIndex;

    public BrowserHistory(String homepage) {
        history.add(homepage);
        currentIndex = 0;
        lastIndex = 0;
    }

    public void visit(String url) {
        currentIndex++;
        if (currentIndex == history.size()) {
            history.add(url);
        } else {
            history.set(currentIndex, url);
        }
        lastIndex = currentIndex;
    }

    public String back(int steps) {
        currentIndex = Math.max(0, currentIndex - steps);
        return history.get(currentIndex);
    }

    public String forward(int steps) {
        currentIndex = Math.min(lastIndex, currentIndex + steps);
        return history.get(currentIndex);
    }
}

class BrowserHistory {
    private final String[] pages = new String[5005];
    private int index;
    private int size;

    public BrowserHistory(String homepage) {
        pages[0] = homepage;
        index = 0;
        size = 1;
    }

    public void visit(String url) {
        index++;
        pages[index] = url;
        size = index + 1;
    }

    public String back(int steps) {
        index -= steps;
        if (index < 0) {
            index = 0;
        }
        return pages[index];
    }

    public String forward(int steps) {
        index += steps;
        if (index >= size) {
            index = size - 1;
        }
        return pages[index];
    }
}

class BrowserHistory {
    private static final class Node {
        String url;
        Node prev;
        Node next;
        Node(String url) {
            this.url = url;
        }
    }

    private Node current;

    public BrowserHistory(String homepage) {
        current = new Node(homepage);
    }

    public void visit(String url) {
        Node node = new Node(url);
        node.prev = current;
        current.next = node;
        current = node;
    }

    public String back(int steps) {
        while (steps > 0 && current.prev != null) {
            current = current.prev;
            steps--;
        }
        return current.url;
    }

    public String forward(int steps) {
        while (steps > 0 && current.next != null) {
            current = current.next;
            steps--;
        }
        return current.url;
    }
}

import java.util.*;

class BrowserHistory {
    private String current;
    private final Deque<String> backStack = new ArrayDeque<>();
    private final Deque<String> forwardStack = new ArrayDeque<>();

    public BrowserHistory(String homepage) {
        current = homepage;
    }

    public void visit(String url) {
        backStack.push(current);
        current = url;
        forwardStack.clear();
    }

    public String back(int steps) {
        while (steps > 0 && !backStack.isEmpty()) {
            forwardStack.push(current);
            current = backStack.pop();
            steps--;
        }
        return current;
    }

    public String forward(int steps) {
        while (steps > 0 && !forwardStack.isEmpty()) {
            backStack.push(current);
            current = forwardStack.pop();
            steps--;
        }
        return current;
    }
}

class BrowserHistory {
    private final String[] urls = new String[5005];
    private final int[] prev = new int[5005];
    private final int[] next = new int[5005];
    private int current;
    private int nextFree;

    public BrowserHistory(String homepage) {
        java.util.Arrays.fill(prev, -1);
        java.util.Arrays.fill(next, -1);
        urls[0] = homepage;
        current = 0;
        nextFree = 1;
    }

    public void visit(String url) {
        int node = nextFree++;
        urls[node] = url;
        prev[node] = current;
        next[node] = -1;
        next[current] = node;
        current = node;
    }

    public String back(int steps) {
        while (steps > 0 && prev[current] != -1) {
            current = prev[current];
            steps--;
        }
        return urls[current];
    }

    public String forward(int steps) {
        while (steps > 0 && next[current] != -1) {
            current = next[current];
            steps--;
        }
        return urls[current];
    }
}
